import type { LocalizedLine } from "./rapportUtils";

/**
 * "Stay with me" support mode: when the patient's words may mean thoughts of
 * self-harm, Amumata pauses the questions and keeps them company until they
 * choose to continue, take a break or stop — with the help lines on screen.
 *
 * Every line is fixed and reviewed in advance (never generated by the AI), and
 * follows safe-messaging guidance: thank them, validate, no judging, no
 * promises, no advice beyond reaching out to a person. Amumata never responds
 * to the details of what was said; that is for the therapist.
 */

/** What the patient chose to do after support mode. */
export type SupportChoice = "continued" | "break" | "ended";

export const SUPPORT_TIMING = {
  /** Quiet time before another gentle line. */
  lineGapMs: 45_000,
  /** Gentle lines after the opening one; then Amumata stays quiet with the help card. */
  maxLines: 4,
  /** "I hear you" when red-flag words come again: at most this often, and this many times. */
  heardGapMs: 20_000,
  maxHeard: 2,
};

