/**
 * Said to go on with the questions. Only clear "continue" words count: the usual
 * "yes" phrases ("wala na", "okay") can mean something else from someone in distress.
 */
const CONTINUE_PHRASES = [
  "continue", "lets continue", "i want to continue", "i can continue", "im ready", "ready", "ready na",
  "ituloy", "ituloy na", "ituloy natin", "tuloy na", "tuloy tayo", "handa na ako", "kaya ko na",
  "padayon", "padayon ta", "padayon na", "ipadayon", "ipadayon na", "andam na ko", "kaya na nako",
];

export function isSupportContinue(text: string): boolean {
  const normalized = text
    .toLowerCase()
    .replace(/[’']/g, "")
    .replace(/[^a-z\s]/g, " ")
    .replace(/\b(po|na lang|lang)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  return CONTINUE_PHRASES.includes(normalized);
}

/** What the room needs to remember while support mode is on. */
export interface SupportPace {
  /** When Amumata last said a line (opening or gentle line). */
  lastLineAt: number;
  /** Gentle lines said so far (not counting the opening). */
  linesSaid: number;
  heardCount: number;
  lastHeardAt: number | null;
}

export function startPace(now: number): SupportPace {
  return { lastLineAt: now, linesSaid: 0, heardCount: 0, lastHeardAt: null };
}

/** The next gentle line to say now, or null (still talking, too soon, or all said). */
export function nextSupportLine(pace: SupportPace, now: number, lastVoiceAt: number | null, voiceActive: boolean): number | null {
  if (voiceActive || pace.linesSaid >= Math.min(SUPPORT_TIMING.maxLines, SUPPORT_LINES.length)) return null;
  const quietSince = Math.max(pace.lastLineAt, lastVoiceAt ?? 0);
  return now - quietSince >= SUPPORT_TIMING.lineGapMs ? pace.linesSaid : null;
}

/** Answer red-flag words said again with "I hear you"? */
export function shouldSayHeard(pace: SupportPace, now: number): boolean {
  if (pace.heardCount >= SUPPORT_TIMING.maxHeard) return false;
  return pace.lastHeardAt === null || now - pace.lastHeardAt >= SUPPORT_TIMING.heardGapMs;
}
